<script setup>import {ref,onBeforeUnmount,nextTick} from 'vue';import {useRoute} from 'vue-router';import {streamChat,demoMode} from '../services/api';import SourceList from '../components/SourceList.vue';const route=useRoute(),question=ref(String(route.query.q||'')),messages=ref([]),busy=ref(false),error=ref(''),box=ref(null);let controller,lastQuestion='';const context={character:route.query.char||null,script:route.query.script||null,document_ids:route.query.id?[String(route.query.id)]:[]};function stop(){controller?.abort()}async function send(q=question.value){if(busy.value||!q.trim())return;lastQuestion=q;question.value='';error.value='';messages.value.push({role:'user',text:q});const reply={role:'assistant',text:'',sources:[],status:'生成中'};messages.value.push(reply);const target=messages.value.at(-1);busy.value=true;controller=new AbortController();try{await streamChat({question:q,context,history:messages.value.slice(0,-2).filter(m=>m.role==='user'||m.status==='已完成').map(m=>({role:m.role,content:m.text})),signal:controller.signal,onDelta:text=>{target.text+=text;nextTick(()=>{if(box.value)box.value.scrollTop=box.value.scrollHeight})},onSources:s=>target.sources=s});target.status='已完成'}catch(e){target.status=e.name==='AbortError'?'已停止':'生成失败';if(e.name!=='AbortError')error.value=e.message}finally{busy.value=false}}function clear(){if(busy.value)return;messages.value=[];error.value=''}onBeforeUnmount(stop);</script><template><section class="section chat-tour-page"><div class="ai-cover"><span class="sub">与文字对话</span><h1>有字可寻，<br>有问可答。</h1><p>把看到的字体、读到的字义，变成你的下一个问题。</p><p class="quiet">向下浏览，开始与 AI 书法伴学对话。</p><span class="ai-cover-glyph" aria-hidden="true">问</span><a class="underlink" href="#chat-conversation" @click.prevent="box?.scrollIntoView({behavior:'smooth'})">开始提问 ↓</a></div><div class="ai-introduction"><span class="sub">本页讲什么 / 学习伴学</span><h2>从欣赏，到理解。</h2><p>你可以询问字体特点、汉字的形与意，或临习前的观察方法。回答以流式文字呈现，可以随时停止；重要的文字学结论请核查资料来源。</p></div><span class="sub">书法伴学 / LEARNING COMPANION</span><h2>一起读懂，笔墨之间。</h2><p class="mode">{{demoMode?'演示模式：本地预设内容逐字显示，非真实 AI。':'DeepSeek 接口模式：真实模型回答；尚未接入检索知识库，请核查重要信息。'}}</p><p v-if="context.character||context.script" class="quiet">当前上下文：{{context.character||context.script}}</p><div class="toolbar"><button @click="question='小篆有什么特点？'">认识小篆</button><button @click="question='请解释山字的形与意'">探索山字</button><button :disabled="busy" @click="clear">清空对话</button></div><div id="chat-conversation" ref="box" class="conversation" aria-live="polite"><p v-if="!messages.length" class="quiet">从一个汉字或字体开始，提出你的第一个问题。</p><article v-for="(m,i) in messages" :key="i" :class="['bubble',m.role]"><small>{{m.role==='user'?'你':'字溯伴学'}} <span v-if="m.status">· {{m.status}}</span></small><p>{{m.text||(m.status==='生成失败'?'本次未收到回答，请查看下方错误提示。':m.status==='已停止'?'已停止生成。':'正在等待回答…')}}</p><SourceList v-if="m.role==='assistant'&&m.status==='已完成'" :sources="m.sources"/></article></div><p v-if="error" class="error" role="alert">{{error}} <button :disabled="busy" @click="send(lastQuestion)">重试</button></p><form class="lookup-form" @submit.prevent="send()"><input v-model="question" aria-label="你的问题" placeholder="想了解哪个汉字？" :disabled="busy"><button v-if="busy" type="button" class="primary" @click="stop">停止生成</button><button v-else class="primary" :disabled="!question.trim()">发送 →</button></form></section></template>




